import { Component, ElementRef, inject } from '@angular/core';

@Component({
  selector: 'pct-avatar',
  templateUrl: './avatar.html',
  styles: [':host [tabindex] { outline: none; }'],
})
export class PctAvatar {
  private readonly el = inject(ElementRef).nativeElement as HTMLElement;
  constructor() {
    this.el.querySelector('[tabindex]');
    this.el.querySelectorAll('[tabindex^="-"]');
    this.el.closest('[tabindex^="-" i]');
    this.el.matches('[tabindex]');
    this.el.setAttribute('tabindex', '5');
  }
}
